1	// Port of PyYAML's error.py — Mark and the YAMLError hierarchy.
2	// Error strings are reproduced character-for-character, since they surface in
3	// the traceback the CPython build prints on stderr.
4	
5	import { LINE_BREAKS_Z as LINE_BREAK_CHARS } from './chars.mjs';
6	
7	export class Mark {
8	  constructor(name, index, line, column, buffer, pointer) {
9	    this.name = name;
10	    this.index = index;
11	    this.line = line;
12	    this.column = column;
13	    // `buffer` is an array of single-code-point strings, so every offset here
14	    // counts code points exactly the way Python's str indexing does.
15	    this.buffer = buffer;
16	    this.pointer = pointer;
17	  }
18	
19	  getSnippet(indent = 4, maxLength = 75) {
20	    if (this.buffer === null || this.buffer === undefined) return null;
21	    let head = '';
22	    let start = this.pointer;
23	    while (start > 0 && !LINE_BREAK_CHARS.includes(this.buffer[start - 1])) {
24	      start -= 1;
25	      if (this.pointer - start > maxLength / 2 - 1) {
26	        head = ' ... ';
27	        start += 5;
28	        break;
29	      }
30	    }
31	    let tail = '';
32	    let end = this.pointer;
33	    while (end < this.buffer.length && !LINE_BREAK_CHARS.includes(this.buffer[end])) {
34	      end += 1;
35	      if (end - this.pointer > maxLength / 2 - 1) {
36	        tail = ' ... ';
37	        end -= 5;
38	        break;
39	      }
40	    }
41	    const snippet = this.buffer.slice(start, end).join('');
42	    return ' '.repeat(indent) + head + snippet + tail + '\n' +
43	      ' '.repeat(indent + this.pointer - start + head.length) + '^';
44	  }
45	
46	  toString() {
47	    const snippet = this.getSnippet();
48	    let where = `  in "${this.name}", line ${this.line + 1}, column ${this.column + 1}`;
49	    if (snippet !== null) where += ':\n' + snippet;
50	    return where;
51	  }
52	}
53	
54	export class YAMLError extends Error {
55	  constructor(message) {
56	    super(message);
57	    // `qualifiedName` mirrors how Python spells the class in a traceback.
58	    this.qualifiedName = 'yaml.error.YAMLError';
59	  }
60	}
61	
62	export class MarkedYAMLError extends YAMLError {
63	  constructor(context = null, contextMark = null, problem = null, problemMark = null, note = null) {
64	    super('');
65	    this.context = context;
66	    this.contextMark = contextMark;
67	    this.problem = problem;
68	    this.problemMark = problemMark;
69	    this.note = note;
70	    this.message = this.buildMessage();
71	    this.qualifiedName = 'yaml.error.MarkedYAMLError';
72	  }
73	
74	  buildMessage() {
75	    const lines = [];
76	    if (this.context !== null) lines.push(this.context);
77	    if (this.contextMark !== null &&
78	      (this.problem === null || this.problemMark === null ||
79	        this.contextMark.name !== this.problemMark.name ||
80	        this.contextMark.line !== this.problemMark.line ||
81	        this.contextMark.column !== this.problemMark.column)) {
82	      lines.push(String(this.contextMark));
83	    }
84	    if (this.problem !== null) lines.push(this.problem);
85	    if (this.problemMark !== null) lines.push(String(this.problemMark));
86	    if (this.note !== null) lines.push(this.note);
87	    return lines.join('\n');
88	  }
89	
90	  toString() {
91	    return this.message;
92	  }
93	}
94	
95	function markedSubclass(qualifiedName) {
96	  return class extends MarkedYAMLError {
97	    constructor(context, contextMark, problem, problemMark, note = null) {
98	      super(context, contextMark, problem, problemMark, note);
99	      this.qualifiedName = qualifiedName;
100	    }
101	  };
102	}
103	
104	export class ReaderError extends YAMLError {
105	  constructor(name, position, character, encoding, reason) {
106	    super('');
107	    this.name = name;
108	    this.character = character;
109	    this.position = position;
110	    this.encoding = encoding;
111	    this.reason = reason;
112	    this.qualifiedName = 'yaml.reader.ReaderError';
113	    this.message = this.buildMessage();
114	  }
115	
116	  buildMessage() {
117	    // The loader is always handed a str, so only PyYAML's unicode branch applies.
118	    const code = this.character.codePointAt(0).toString(16);
119	    return `unacceptable character #x${code}: ${this.reason}\n` +
120	      `  in "${this.name}", position ${this.position}`;
121	  }
122	
123	  toString() { return this.message; }
124	}
125	
126	export const ScannerError = markedSubclass('yaml.scanner.ScannerError');
127	export const ParserError = markedSubclass('yaml.parser.ParserError');
128	export const ComposerError = markedSubclass('yaml.composer.ComposerError');
129	export const ConstructorError = markedSubclass('yaml.constructor.ConstructorError');
130	
131	export class SerializerError extends YAMLError {
132	  constructor(message) {
133	    super(message);
134	    this.qualifiedName = 'yaml.serializer.SerializerError';
135	  }
136	}
137	
138	export class RepresenterError extends YAMLError {
139	  constructor(message) {
140	    super(message);
141	    this.qualifiedName = 'yaml.representer.RepresenterError';
142	  }
143	}
144	
145	export class EmitterError extends YAMLError {
146	  constructor(message) {
147	    super(message);
148	    this.qualifiedName = 'yaml.emitter.EmitterError';
149	  }
150	}
151	
152	// Stand-ins for the builtin Python exceptions PyYAML lets escape unchanged.
153	export class PyValueError extends Error {
154	  constructor(message) {
155	    super(message);
156	    this.qualifiedName = 'ValueError';
157	    this.message = message;
158	  }
159	}
160	
161	export class PyTypeError extends Error {
162	  constructor(message) {
163	    super(message);
164	    this.qualifiedName = 'TypeError';
165	    this.message = message;
166	  }
167	}
