1	// Port of PyYAML's events.py.
2	
3	class Event {
4	  constructor(startMark = null, endMark = null) {
5	    this.startMark = startMark;
6	    this.endMark = endMark;
7	  }
8	}
9	
10	class NodeEvent extends Event {
11	  constructor(anchor, startMark = null, endMark = null) {
12	    super(startMark, endMark);
13	    this.anchor = anchor;
14	  }
15	}
16	
17	class CollectionStartEvent extends NodeEvent {
18	  constructor(anchor, tag, implicit, startMark = null, endMark = null, flowStyle = null) {
19	    super(anchor, startMark, endMark);
20	    this.tag = tag;
21	    this.implicit = implicit;
22	    this.flowStyle = flowStyle;
23	  }
24	}
25	
26	class CollectionEndEvent extends Event {}
27	
28	export class StreamStartEvent extends Event {
29	  constructor(startMark = null, endMark = null, encoding = null) {
30	    super(startMark, endMark);
31	    this.encoding = encoding;
32	  }
33	}
34	export class StreamEndEvent extends Event {}
35	
36	export class DocumentStartEvent extends Event {
37	  constructor(startMark = null, endMark = null, explicit = null, version = null, tags = null) {
38	    super(startMark, endMark);
39	    this.explicit = explicit;
40	    this.version = version;
41	    this.tags = tags;
42	  }
43	}
44	
45	export class DocumentEndEvent extends Event {
46	  constructor(startMark = null, endMark = null, explicit = null) {
47	    super(startMark, endMark);
48	    this.explicit = explicit;
49	  }
50	}
51	
52	export class AliasEvent extends NodeEvent {}
53	
54	export class ScalarEvent extends NodeEvent {
55	  constructor(anchor, tag, implicit, value, startMark = null, endMark = null, style = null) {
56	    super(anchor, startMark, endMark);
57	    this.tag = tag;
58	    this.implicit = implicit;
59	    this.value = value;
60	    this.style = style;
61	  }
62	}
63	
64	export class SequenceStartEvent extends CollectionStartEvent {}
65	export class SequenceEndEvent extends CollectionEndEvent {}
66	export class MappingStartEvent extends CollectionStartEvent {}
67	export class MappingEndEvent extends CollectionEndEvent {}
68	
69	export { Event, NodeEvent, CollectionStartEvent, CollectionEndEvent };
