1	// Minimal in-memory sink standing in for Python's io.StringIO.
2	
3	export class StringStream {
4	  constructor() {
5	    this.parts = [];
6	  }
7	
8	  write(data) {
9	    this.parts.push(data);
10	  }
11	
12	  getvalue() {
13	    return this.parts.join('');
14	  }
15	}
